actAPI.getSaveData());\n\t\t\t\t\n\t\t\t\tvar saveDatas = event.ReactAPI.getSaveData();\n\t\t\t\t//删除的企业资质Ids\n\t\t\t\tvar deletedCompanyCertIds = saveDatas.dgDeletedIds.dg1575277481175;\n\t\t\t\t//企业资质列表数据\n\t\t\t\tvar companyCertList = saveDatas.dgList.dg1575277481175;\n\t\t\t\t$.ajax({\n\t\t\t\t\turl: \"/msService/Qualify/companyCertificate/companyCert/saveCompanyCertPTData\",\n\t\t\t\t\ttype: \"post\",\n\t\t\t\t\tasync: false,\n\t\t\t\t\theaders:{''Content-Type'':''application/json;charset=utf8''},\n\t\t\t\t\tdataType:\"json\",\n\t\t\t\t\t//data: { deletedStaffCertIds:deletedStaffCertIds, staffCertList:staffCertList },//List<Map<String, Object>>\n\t\t\t\t\tdata: JSON.stringify({ deletedCompanyCertIds:deletedCompanyCertIds, companyCertList:companyCertList }),\n\t\t\t\t\tsuccess: function(res) {\n\t\t\t\t\t\tconsole.log(res);\n\t\t\t\t\t\tif(res.data.dealSuccessFlag) {\n\t\t\t\t\t\t\tReactAPI.destroyDialog(\"companyCertEditDialog\");\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t},\n\t\t\t//okText:\"保存\",    \n\t\t\tokText: ReactAPI.international.getText(\"Button.text.save\"),\n\t\t\tonCancel:function(){\n\t\t\t\tReactAPI.destroyDialog(\"companyCertEditDialog\");\n\t\t\t}\n\t\t});\n\t});\n}","funcname":"onclick=''setCompanyCert()''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":true,"cellCode":"cell_1575286168399_6434","buttonoperationcode":"certCompanyList_companyCertSet_add_Qualify_1.0.0_companyCertificate_certCompanyList","isHide":false,"showname":"企业资质设置","ecEnv":"product","pc":"__pc__=Y2VydENvbXBhbnlMaXN0X2NvbXBhbnlDZXJ0U2V0X2FkZF9RdWFsaWZ5XzEuMC4wX2NvbXBhbnlDZXJ0aWZpY2F0ZV9jZXJ0Q29tcGFueUxpc3R8","regionType":"BUTTON","iscallback":false,"modelCode":"Qualify_1.0.0_companyCertificate_CertCompany","namekey":"Qualify.buttonPropertyshowName.randon1575286208703.flag","funcbody_es5":"function setCompanyCert() {\n\n\tvar selRows = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"Qualify_1.0.0_companyCertificate_certCom